scripts.假和尚对话.txt:
//和假和尚对话

	If ($Event == 390) @Event390;
	If ($Event == 400) @Event400;
	
	Return;
		
@Event390:		
	Say("张琳心：好啊，原来是个狗肉和尚——躲在这里吃狗肉。", 21);
	Say("狗肉和尚：你，你们是谁！敢管老子的……呃，贫道，呃——贫僧的闲事。", 0);
	Sleep(500);
	Say("张琳心（悄声地）：独孤哥哥，这和尚有些古怪。", 21);
	Say("独孤剑：嗯。", 1);
	Sleep(500);
	Say("狗肉和尚：哼！你们是从哪里来的，孤男寡女，竟然跑到少林寺来撒野！", 0);
	Say("张琳心（故作神秘）：不好，独孤左使，我们的行踪被这个臭和尚发现了。先制住他再说。", 27);
	Say("独孤剑：啊？", 8);
	SetNpcRes("假和尚", "npcres074_假和尚.ini");
	StopMusic();
	PlayMusic("激战.mp3");
	SetNpcRelation("假和尚", 1);
	SetNpcDeathScript("假和尚", "假和尚死亡.txt");
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetNpcRelation("张琳心", 0);
	SetNpcScript("张琳心", "");
	Assign($Event, 395);
	Return;
	
@Event400:	
	Say("假和尚：两位饶命啊，小的只是跑腿的。", 0);
	Return;

scripts.假和尚死亡.txt:
//假和尚死亡

	FadeOut();
	StopMusic();
	PlayMusic("禅音.mp3");
	ClearBody();
	DelNpc("假和尚");
	SaveNpc();
	SaveObj();
	SetNpcKind("张琳心", 1);
	SetNpcRelation("张琳心", 2);
	SetPlayerPos(9, 26);
	SetPlayerDir(4);	
	SetNpcPos("张琳心", 8, 25);
	SetNpcDir("张琳心", 6);
	AddNpc("npc074_跪着的假和尚.ini", 9, 23, 1); 
	SetNpcScript("假和尚", "假和尚对话.txt");
	ClearEffect();
	FadeIn();
	
	Say("张琳心（故作神秘）：独孤左使，你带够了份量没有？我们赏他双份的神功散，让他化成一摊烂泥。这样就神不知鬼不觉了。", 21);
	Say("独孤剑：嘿嘿……本座这里有的是。", 2);
	Say("狗肉和尚：神……神功散！就是那种服用后武功慢慢消失，最后变成比常人还虚弱的那种神功散，是不是？", 0);
	Say("张琳心：不错！不过，你只说对了一半，这是很小剂量的功效，不过我们要给你多用一些，保证让你像一摊烂泥一样被化去于无形。阿弥陀佛，善哉善哉！", 95);
	Say("狗肉和尚：神功散是……是本教独门奇药，难道……两位也是本教中人。饶命啊，小的是黄剑堂的弟子，两位不要误会。", 0);
	Say("独孤剑：你是五……本教弟子？", 6);
	Say("假和尚：正是，教主吩咐小的来少林寺给黄堂主送信的，要黄堂主先回总坛，修改暗杀计划。", 0);
	Say("张琳心：你说你是本教弟子，那本教的切口是什么？", 21);
	Say("假和尚：<enter>五彩闪华轮，圣色照乾坤。<enter>摩尼教千岁，万世奉王灯。", 0);
	Say("独孤剑：谁是黄剑堂堂主？", 1);
	Say("假和尚：黄堂主他……你，你们既是教中派来的人，怎，怎会不知道黄堂主是谁。你们……", 0);
	Watch("独孤剑", "张琳心", 0);
	Say("张琳心：独孤哥哥，事情已经清楚了，黄堂主就是偷袭方丈大师之人。我有一计，可以引出这个神秘的黄堂主。", 21);
	Say("独孤剑：那我们即刻去找无虚大师。", 1);
	Say("张琳心：这个假和尚暂且不杀，留着还有用处。先去找无虚大师吧。", 21);
	SetNpcKind("张琳心", 3);
	SetNpcScript("张琳心", "张琳心对话.txt");
	Assign($Event, 400);
	Memo("独孤剑和张琳心来到塔林，抓到了一个假扮成和尚的五色教徒。");
	SetMapTrap(1,"trap01.txt");
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 390) @Event390;
	If ($Event == 400) @Event400;
	If ($Event == 410) @Event410;
	If ($Event == 420) @Event420;
	Return;
	
@Event390:
	Say("独孤剑：这塔林里好生肃穆。", 1);
	Say("张琳心：少林寺塔林是少林寺历代高僧的坟茔。高僧圆寂后将其尸骨安放地宫，上面建塔，以示功德。", 1);
	Return;
	
@Event400:
	Say("独孤剑：我们去找无虚大师吧。", 1);		
	Return;
	
@Event410:
	Say("张琳心：我们也走吧。", 21);
	Return;	
	
@Event420:
	Say("张琳心：我们下山吧！", 21);
	Return;

scripts.无相和尚死亡.txt:
//无相死亡
	
	Sleep(1200);
	FadeOut();
	Say("无相：黄毛小儿，竟敢戏弄于我！我一定不会放过你的！", 73);
	ClearBody();
	DelNpc("无相和尚");
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("禅音.mp3");
	SetNpcKind("张琳心", 1);
	SetPlayerPos(9, 25);
	SetPlayerDir(2);
	SetNpcPos("张琳心", 9, 26);
	SetNpcDir("张琳心", 3);
	SetNpcKind("张琳心", 3);
	SetNpcRelation("张琳心", 2);
	SetNpcScript("张琳心", "张琳心对话.txt");
	SetNpcPos("无虚大师", 8, 25);
	SetNpcDir("无虚大师", 7);
	SetNpcPos("少林一代弟子", 8, 28);
	SetNpcDir("少林一代弟子", 5);
	SetNpcPos("少林二代弟子", 8, 24);
	SetNpcDir("少林二代弟子", 7);
	ClearEffect();
	FadeIn();
		
	Say("张琳心：可惜，让他跑掉了……", 21);
	Say("无虚大师：阿弥陀佛，罪过，罪过！几十年清修难化心中恶念，一念之差功德全消，唉！", 56);
	Say("独孤剑：大师如何不抓住他？", 1);
	Say("无虚大师：阿弥陀佛，无相师弟魔障在心，已造杀孽，我佛迟早降施报应，老衲何必再造孽缘？由他去吧。独孤少侠，看来五色教定然不会放过你，你今后的路途更加危机重重。", 56);
	Say("独孤剑：独孤剑纵然粉身碎骨，也要和五色教周旋到底！", 9);
	Say("无虚大师：我们每个人对这场武林危难都肩负重责。独孤少侠，张姑娘，老衲今日便各传你们一套武功，助你们日后惩奸除恶，将武林正义发扬光大。", 56);
	Say("独孤剑：这……我们并非少林弟子，贵派不传的绝学，我们恐怕不便修习……", 1);
	Say("无虚大师：老衲都没有门户之见，少侠又何必心存顾虑？呵呵，来来来……", 56);
	
	FadeOut();
	DelNpc("少林一代弟子");
	DelNpc("少林二代弟子");
	DelNpc("假和尚");
	SaveNpc();
	SetNpcKind("张琳心", 1);
	SetPlayerPos(16, 30);
	SetPlayerDir(4);
	SetNpcPos("张琳心", 15, 29);
	SetNpcDir("张琳心", 5);
	SetNpcPos("无虚大师", 16, 28);
	SetNpcDir("无虚大师", 7);
	FadeIn();
	SetNpcKind("张琳心", 3);
	Say("无虚大师：少侠看好，这便是老衲新悟成的绝学“龙爪虎抓”。", 56);
	SetNpcMagicFile("无虚大师", "magic010_龙爪虎抓.ini");
	NpcAttack("无虚大师", 17, 28); 
	Sleep(1000);
	AddMagic("magic010_龙爪虎抓.ini");  
	SetMagicLevel("magic010_龙爪虎抓.ini", 1);
	FullLife();
	FullThew();
	FullThew();
	Say("无虚大师：张姑娘，请看好，这招便是“梅花弄影”。", 56);
	SetNpcMagicFile("无虚大师", "magic022_梅花弄影.ini");
	NpcAttack("无虚大师", 17, 28); 
	Sleep(1000);
	AddOneMagic("张琳心", "magic022_梅花弄影.ini"); 
	//SetMagicLevel("magic022_梅花弄影.ini", 3);
	SetNpcKind("张琳心", 1);	
	SetNpcDir("无虚大师", 0);
	Say("独孤剑：多谢大师教诲！", 2);
	Say("无虚大师：你们二位天资聪颖，假以时日，前途不可限量。我中原武林才俊辈出，他五色教想颠覆中原武林，只怕是痴心妄想！", 56);
	Say("独孤剑：我们打算即刻赶往宋军大营，以防韩岳两位元帅遭遇不测。", 1);
	Say("无虚大师：你们下了少室山，往东走，经过朱仙镇就可到达宋军大营了。", 56);
	Say("无虚大师：少林藏经阁中有本寺历代高僧留下的秘笈宝典，既有高深的佛法，也有武功绝学，老衲的师弟无穷日前也正在钻研一套奇门武功。少侠不妨前往一览，说不得能对少侠有所助益。", 56);
	Say("独孤剑：多谢大师！", 2);
	Say("无虚大师：阿弥陀佛！", 56);
	
	NpcGoto("无虚大师", 17, 35);
	NpcGoto("无虚大师", 17, 39);
	NpcGoto("无虚大师", 17, 43);
	DelNpc("无虚大师");
	SaveNpc();
	
	Say("张琳心：独孤哥哥，我们也走吧！", 21);
	Say("独孤剑：嗯！", 1); 
	SetNpcKind("张琳心", 3);
	SetMapTrap(1,"trap01.txt");
	Assign($Event, 410);
	Memo("张琳心使妙计找出了少林寺内奸无相。为表感谢，无虚大师各传两人一套武功，并建议两人去藏经阁拜访无穷。");
	Return;

